package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Input() {
        Complex nan = Complex.NaN;
        Complex divisor = new Complex(1.0, 1.0);
        Complex result = nan.divide(divisor);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_Divisor() {
        Complex c = new Complex(1.0, 1.0);
        Complex nanDivisor = Complex.NaN;
        Complex result = c.divide(nanDivisor);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ResultNaN() {
        // if (divisor.isZero) return isZero ? NaN : INF;
        // Case: 0 / 0 = NaN
        Complex zero = Complex.ZERO;
        Complex result = zero.divide(zero);
        assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ResultINF() {
        // Case: 1 / 0 = INF
        Complex c = new Complex(1.0, 1.0);
        Complex zero = Complex.ZERO;
        Complex result = c.divide(zero);
        assertTrue(result.isInfinite());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteDividend() {
        // if (divisor.isInfinite() && !isInfinite()) return ZERO;
        Complex c = new Complex(1.0, 1.0);
        Complex inf = Complex.INF;
        Complex result = c.divide(inf);
        assertEquals(0.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // if (FastMath.abs(c) < FastMath.abs(d))
        // Let divisor = 1 + 2i -> |1| < |2|
        Complex c = new Complex(2.0, 4.0); // (2 + 4i) / (1 + 2i) = 2
        Complex divisor = new Complex(1.0, 2.0);
        Complex result = c.divide(divisor);
        assertEquals(2.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_Branch_AbsC_GreaterOrEqual_AbsD() {
        // else branch: if (FastMath.abs(c) >= FastMath.abs(d))
        // Let divisor = 2 + 1i -> |2| > |1|
        Complex c = new Complex(4.0, 2.0); // (4 + 2i) / (2 + 1i) = 2
        Complex divisor = new Complex(2.0, 1.0);
        Complex result = c.divide(divisor);
        assertEquals(2.0, result.getReal(), DELTA);
        assertEquals(0.0, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_StandardCalculation() {
        // (1 + 2i) / (3 + 4i)
        // denominator = (1*3 + 2*4) = 11
        // real = (1*3 + 2*4)/11 = 11/11 = 1? No.
        // Using formula: (a+bi)/(c+di) = [(ac+bd)/(c^2+d^2)] + i[(bc-ad)/(c^2+d^2)]
        // (1+2i)/(3+4i) = [(3+8)/25] + i[(6-4)/25] = 11/25 + i(2/25) = 0.44 + 0.08i
        Complex c = new Complex(1.0, 2.0);
        Complex divisor = new Complex(3.0, 4.0);
        Complex result = c.divide(divisor);
        assertEquals(0.44, result.getReal(), DELTA);
        assertEquals(0.08, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_BothInfinite() {
        // if (divisor.isInfinite() && !isInfinite()) -> This branch is skipped if both are infinite
        // If both are infinite, it goes to the math logic.
        Complex inf = Complex.INF;
        Complex result = inf.divide(inf);
        // INF / INF in this implementation logic will likely result in NaN or a specific value
        // based on the math logic.
        assertFalse(result.isZero());
    }
}
